import { defineConfig } from "orval";

// `make gen-api` writes openapi.yaml from the backend, then runs this. Never edit src/generated by hand.
export default defineConfig({
  client: {
    input: "./openapi.yaml",
    output: {
      target: "./src/generated/client.ts",
      schemas: "./src/generated/models",
      client: "react-query",
      httpClient: "fetch",
      clean: true,
      override: {
        mutator: { path: "./src/http.ts", name: "apiFetch" },
        // Functions return the data itself; a failure throws ApiError.
        fetch: { includeHttpResponseReturnType: false },
      },
    },
  },
  zod: {
    input: "./openapi.yaml",
    output: {
      target: "./src/generated/zod.ts",
      client: "zod",
    },
  },
});
